insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"nouns_festival_q02_finish","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}},{"key":"nouns_festival_q02_start","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}},{"key":"nouns_festival_q03_finish","speaker_external_id":"Farmer","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}},{"key":"nouns_festival_q03_progress","speaker_external_id":"Farmer","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}},{"key":"nouns_festival_q03_start","speaker_external_id":"Farmer","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}},{"key":"nouns_festival_q04_finish","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}},{"key":"nouns_festival_q04_progress","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}},{"key":"nouns_festival_q04_start","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}},{"key":"nouns_festival_q05_finish","speaker_external_id":"Main Gate Gaurd 2","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}},{"key":"nouns_festival_q05_progress","speaker_external_id":"Main Gate Gaurd 2","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}},{"key":"nouns_festival_q05_start","speaker_external_id":"Main Gate Gaurd 2","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}},{"key":"nouns_festival_q06_finish","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}},{"key":"nouns_festival_q06_progress","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}},{"key":"nouns_festival_q06_start","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\nouns_festival.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"nouns_festival_q02_finish","locale":"he","line_order":0,"content":"כל הכבוד! סיימתם את ההכנות הראשונות לפסטיבל.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q02_finish","locale":"he","line_order":1,"content":"עכשיו לכו אל החקלאי Farmer בפארק ורד הפרחים. הוא מחכה לכם עם משימת החיות.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q02_start","locale":"he","line_order":0,"content":"ברוכים הבאים לפסטיבל. אני צריך עזרה לפני שהשערים ייפתחו.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q02_start","locale":"he","line_order":1,"content":"החקלאי ביקש ממני להכין כמה דברים לדוכן שלו, אבל אני לא מספיק לבד.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q02_start","locale":"he","line_order":2,"content":"עזרו לי לסדר את האזור, ואחר כך אשלח אתכם אליו כדי לעזור עם החיות.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q03_finish","locale":"he","line_order":0,"content":"מצוין! החיות מוכנות עכשיו למופע.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q03_finish","locale":"he","line_order":1,"content":"עכשיו לכו אל ויל Will The Smith בבית הבנאים. הוא צריך עזרה עם חפצי הפסטיבל.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q03_progress","locale":"he","line_order":0,"content":"מצוין, החיות הראשונות כבר יכולות לחזור למתחם.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q03_progress","locale":"he","line_order":1,"content":"נשאר עוד שלט אחד למצוא לפני שהמופע יתחיל.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q03_start","locale":"he","line_order":0,"content":"שלום! החיות של המופע ברחו בזמן שהתכוננתי לפסטיבל.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q03_start","locale":"he","line_order":1,"content":"עזרו לי למצוא את השלטים שלהן ולהחזיר את המופע למסלול.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q04_finish","locale":"he","line_order":0,"content":"נהדר! החפצים מוכנים והדוכן מסודר.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q04_finish","locale":"he","line_order":1,"content":"לכו אל גאריק Garrick the Unmoving בשער הממלכה. הוא מחכה לכם עם המשימה הבאה.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q04_progress","locale":"he","line_order":0,"content":"יפה, רוב הדברים כבר במקום.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q04_progress","locale":"he","line_order":1,"content":"נשאר עוד חפץ אחד, ואז הדוכן יהיה מוכן.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q04_start","locale":"he","line_order":0,"content":"החקלאי שלח אתכם אליי? טוב שהגעתם, כי הדוכן שלי עדיין מבולגן.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q04_start","locale":"he","line_order":1,"content":"הכלים והקישוטים התפזרו, והמבקרים יגיעו בקרוב. עזרו לי לסדר אותם.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q05_finish","locale":"he","line_order":0,"content":"כל הכבוד! השלטים ליד השער ברורים לאורחים.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q05_finish","locale":"he","line_order":1,"content":"עכשיו חזרו אל ראש הכפר Village Head בפארק ורד הפרחים. הוא ייתן לכם את המשימה האחרונה.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q05_progress","locale":"he","line_order":0,"content":"כל הכבוד, השלטים של האנשים כבר ברורים.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q05_progress","locale":"he","line_order":1,"content":"נשאר עוד שלט אחד ליד השער.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q05_start","locale":"he","line_order":0,"content":"הנפח שלח אתכם אל השער? בדיוק בזמן.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q05_start","locale":"he","line_order":1,"content":"השלטים ליד הכניסה התבלבלו, והאורחים לא יודעים מי נמצא כאן ולאן ללכת.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q05_start","locale":"he","line_order":2,"content":"עזרו לי לסדר את השלטים לפני שהקהל יגיע.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q06_finish","locale":"he","line_order":0,"content":"כל הכבוד! השלמתם את כל שלטי הפסטיבל.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q06_finish","locale":"he","line_order":1,"content":"עכשיו האורחים יכולים לקרוא את השלטים ולהגיע לכל דוכן. תודה על העזרה!","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q06_progress","locale":"he","line_order":0,"content":"מצוין, השלטים כבר עוזרים לאורחים למצוא את הדרך.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q06_progress","locale":"he","line_order":1,"content":"נשארו רק השלטים האחרונים ליד הכיכר.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q06_start","locale":"he","line_order":0,"content":"גאריק שלח אתכם אליי. עכשיו נוכל לפתוח את הפסטיבל.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q06_start","locale":"he","line_order":1,"content":"נשארו כמה שלטים אחרונים, והאורחים צריכים להבין אותם במהירות.","line_format":"plain_text"},{"dialogue_key":"nouns_festival_q06_start","locale":"he","line_order":2,"content":"עזרו לי לסדר את המשפטים שעל השלטים, כדי שאף אחד לא ילך לאיבוד.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
